/* Print14 forwards &pPtr to Print_main, which reads the format and its arguments from consecutive words.
 * DS passes one extra zero word after the string in the three Print14 calls below (sw zero,0x14(sp)). */
typedef long (*PRINT14_VA)(ULONG x, ULONG y, ULONG c, ULONG p, UCHAR *pPtr, ...);

/* DS 0x80010a1c */
UCHAR s_Moji_next_mark_80010a1c[8] = {
	47, 0, 0, 0, 0, 0, 0, 0
};

/* DS 0x80010a40 */
UCHAR s_Moji_sel_cursor_80010a40[4] = {
	38, 0, 0, 0
};


/* Moji.Prim_sprt[bank] (14-dot SPRT, 0x1400 per bank, DS 0x800e2c30) and
 * Moji.Prim_sprt_8[bank] (8-dot SPRT_8, 0x1800 per bank, DS 0x800e5430).
 * Moji.pPrim14_cur / pPrim8_cur walk the current bank; a bank is full when the
 * cursor reaches Prim_sprt[bank + 1] / Prim_sprt_8[bank + 1]. */

/* DS 0x8002fa00 (Print8) */
long Print8(ULONG x, ULONG y, ULONG c, ULONG p, UCHAR *pPtr)
{
    long Len;

    Len = Print_main(x, y, c << 4 | p, &pPtr);
    return Len;
}

/* Print8 and Print14 differ only in the font flag: Print14 adds 0x200 to the attribute word, which
 * selects the 14-dot glyph set (Print8 leaves it clear). Both return the length printed. */
/* DS 0x8002fa28 (Print14) */
long Print14(ULONG x, ULONG y, ULONG c, ULONG p, UCHAR *pPtr)
{
    long Len;

    c <<= 4;
    p |= 0x200;
    Len = Print_main(x, y, c | p, &pPtr);
    return Len;
}

/* Text entry header at the start of each Moji_buff entry: SHORT X at +0, SHORT Y at +2,
 * USHORT Attr at +4; glyph codes follow from +6. Print_main writes it; moji_trans_main reads
 * it (retail DS 0x800316a8: "lh a1,0x0(a0)" DS 0x800316d0, "lh v1,0x0(a0)" after +2 at
 * DS 0x800316d8, "lhu v0,0x0(a0)" after +4 at DS 0x800316e0, then a0 = entry + 4 is passed on). */
typedef struct {
	SHORT  X;
	SHORT  Y;
	USHORT Attr;
} MOJI_ENTRY;

/* DS 0x8002fa54 (Print_main) */
long Print_main(ULONG x, ULONG y, ULONG attr, UCHAR **pSave)
{
    UCHAR ch;
    UCHAR *pEntry;          /* start of this entry in Moji_buff */
    UCHAR *pFmt;            /* format string cursor */
    UCHAR *pOut;            /* output cursor */
    UCHAR *pArg;            /* current argument (pointer or value) */
    UCHAR *pRem;            /* width-digit scan cursor */
    UCHAR **pAp;            /* current argument slot */
    UCHAR **pApNext;        /* argument slot after this format item */
    LONG j;                 /* index of the current argument (number of valid specs so far) */
    LONG jNext;             /* j after this format item; committed only for valid specs */
    LONG Width;             /* field width (H_ctr) */
    LONG Sign;              /* 1 or -1 (pm) */
    LONG Val;               /* remaining value being converted */
    LONG Abs_val;
    LONG Keta;              /* number of digits */
    LONG Div;               /* current power of ten */
    LONG Abs_rem;
    LONG Pad;
    LONG Digit;
    LONG Len;               /* return value: characters written */
    CHAR *pDigit = ascii_tbl[0];   /* digit table for the two digit-store loops */
    volatile UCHAR Pad_stack[12];  /* retail frame is 24 bytes; 12 of them are its s0-s2 saves and the other 12 are never addressed. This array is never read or written and only supplies those bytes. */

    Len = 0;
    pFmt = *pSave;
    if (*pFmt != 0 && Moji.pBuff_ptr < Moji.Moji_buff + 0x2c0) {
        pEntry = Moji.pBuff_ptr;
        ((MOJI_ENTRY *)pEntry)->X = (SHORT)x;
        ((MOJI_ENTRY *)pEntry)->Y = (SHORT)y;
        ((MOJI_ENTRY *)pEntry)->Attr = (USHORT)attr;
        pOut = pEntry + sizeof(MOJI_ENTRY);
        pAp = pSave + 1;
        j = 0;
        do {
            if (*pFmt == 0x25) {
                jNext = j + 1;
                pApNext = pAp + 1;
                pArg = *pAp;
                Width = 0;
                pRem = pFmt + 1;
                ch = pFmt[1];
                while ((UINT)(ch - 0x30) < 10) {
                    ch = *pRem;
                    pRem++;
                    Width = Width * 10 - 0x30 + ch;
                    ch = *pRem;
                }
                ch = *pRem;
                pFmt = pRem + 1;
                switch (ch) {
                case 0x25:
                    *pOut = 0x25;
                    pOut++;
                    break;
                case 0x73:
                    ch = *pArg;
                    while (ch != 0) {
                        pArg++;
                        *pOut = ch;
                        pOut++;
                        ch = *pArg;
                    }
                    break;
                case 99:
                    *pOut = (UCHAR)(ULONG)pArg;
                    pOut++;
                    break;
                case 100:
                    Val = (LONG)pArg;
                    Sign = 1;
                    if (Val < 0) {
                        Sign = -1;
                        *pOut = 0x2d;
                        pOut++;
                    }
                    Abs_val = Val * Sign;
                    Keta = 1;
                    Div = 1;
                    Abs_rem = Abs_val;
                    while (9 < Abs_rem) {
                        Div *= 10;
                        Abs_rem = Abs_val / Div;
                        Keta++;
                    }
                    if (Width == 0) {
                        do {
                            Digit = Val / Div;
                            Val %= Div;
                            Div /= 10;
                            Keta--;
                            *pOut = pDigit[(Digit % 10) * Sign];
                            pOut++;
                        } while (Keta != 0);
                    }
                    else {
                        Pad = Width - Keta;
                        if (Sign == -1) {
                            while (1) {
                                Pad--;
                                Width--;
                                if (Pad < 1) break;
                                *pOut = 0x2d;
                                pOut[-1] = 0x20;
                                pOut++;
                            }
                        }
                        else {
                            for (; 0 < Pad; Pad = Pad - 1) {
                                *pOut = 0x20;
                                pOut++;
                                Width--;
                            }
                        }
                        for (; Width != 0; Width = Width - 1) {
                            Digit = Val / Div;
                            Val %= Div;
                            Div /= 10;
                            *pOut = pDigit[(Digit % 10) * Sign];
                            pOut++;
                        }
                    }
                    break;
                default:
                    /* retail: argument slot is recounted from j and the format
                     * pointer is replaced by that count (kept as decompiled) */
                    pAp = pSave + 1;
                    pFmt = (UCHAR *)0;
                    if (0 < j) {
                        do {
                            pFmt++;
                            pAp++;
                        } while ((LONG)pFmt < j);
                    }
                    goto plain_char;
                }
            }
            else {
plain_char:
                ch = *pFmt;
                pFmt++;
                *pOut = ch;
                pApNext = pAp;
                jNext = j;
spec_done:
                pOut++;
            }
            pAp = pApNext;
            j = jNext;
        } while (*pFmt != 0);
        *pOut = 0;
        Len = (LONG)pOut - (LONG)Moji.pBuff_ptr - (LONG)sizeof(MOJI_ENTRY);
        Moji.pBuff_ptr = (UCHAR *)((ULONG)(pOut + 2) & 0xfffffffeUL);
    }
    return Len;
}

/* DS 0x8002fe38 (Mess_set) */
long Mess_set(ULONG Pos_xy, USHORT Attr, ULONG Mess_no, ULONG Stop_data)
{
    MOJIDISP *pMoji = &Moji;
    tagGLOBAL *pG = &G;
    UCHAR *pTop;

    /* A message is already on screen (Mess_flg bit 0x80): report -1 and change nothing. */
    if ((Moji.Mess_flg & 0x80) != 0) {
        return -1;
    }
    Moji.Mess_attr = 3;
    Moji.Mess_flg = 0x80;
    Moji.Stop_data = Stop_data;
    Moji.Mess_r_no0 = 0;
    G.Status_flg |= STAT_PL_BUSY;
    Moji.Stop_keep = G.Stop_flg;
    /* Attribute bits 0x300 pick a fixed message box (0x100 upper, 0x200 lower, 0x300 room message); the
     * other values take the caller's position and attribute. System_flg bits 0x840 == 0x40 switch the
     * text source to the second table set (mess_etc_data, mess_u_data) and set attribute bit 0x4000. */
    switch (Attr & 0x300) {
    case 0x100:
        Moji.Pos_x_def = 0x22;
        Moji.Pos_y_def = 0xb9;
        Moji.Mess_attr = 0x2003;
        Moji.Mess_type = 0x80;
        if ((G.System_flg & 0x840) == 0x40) {
            Moji.Mess_attr = 0x6003;
            Moji.Mess_top = mess_u_data + mess_u_ofs[Mess_no];
        }
        else {
            Moji.Mess_top = mess_tbl_data + mess_tbl_ofs[Mess_no];
        }
        return 0;
    case 0x200:
        Moji.Pos_x_def = 0x22;
        Moji.Pos_y_def = 0xba;
        Moji.Mess_attr = 0x403;
        Moji.Mess_type = 0x80;
        if ((G.System_flg & 0x840) == 0x40) {
            Moji.Mess_attr = 0x4403;
            Moji.Mess_top = mess_etc_data + mess_etc_ofs[Mess_no];
        }
        else {
            Moji.Mess_top = mess_sub_data + mess_sub_ofs[Mess_no];
        }
        return 0;
    case 0x300:
        Moji.Pos_x_def = 0x22;
        Moji.Pos_y_def = 0xb9;
        Moji.Mess_attr = 0x803;
        Moji.Mess_type = 0x80;
        if ((Attr & 1) != 0) {
            Moji.Mess_attr = 0x4803;
        }
        if ((G.System_flg & 0x840) == 0x40) {
            Moji.Mess_attr |= 0x4000;
            Moji.Mess_top = (G.pRoom)->pMessage_sub;
        }
        else {
            Moji.Mess_top = (G.pRoom)->pMessage;
        }
        goto top_from_room;
    default:
        pMoji->Pos_y_def = (USHORT)(Pos_xy >> 16);
        pMoji->Mess_type = (Attr & 0x8000) >> 8;
        pMoji->Pos_x_def = (USHORT)Pos_xy;
        pMoji->Mess_attr = Attr;
        switch (Attr & 0xc00) {
        case 0x400:
            if ((G.System_flg & 0x840) == 0x40) {
                pMoji->Mess_attr = Attr | 0x4000;
                pTop = mess_etc_data + mess_etc_ofs[Mess_no];
            }
            else {
                pTop = mess_sub_data + mess_sub_ofs[Mess_no];
            }
            break;
        case 0:
            if ((G.System_flg & 0x840) == 0x40) {
                pMoji->Mess_attr = Attr | 0x4000;
                pTop = mess_u_data + mess_u_ofs[Mess_no];
            }
            else {
                pTop = mess_tbl_data + mess_tbl_ofs[Mess_no];
            }
            break;
        case 0x800:
            if ((G.System_flg & 0x840) == 0x40) {
                pMoji->Mess_attr = Attr | 0x4000;
                pMoji->Mess_top = (pG->pRoom)->pMessage_sub;
            }
            else {
                pMoji->Mess_top = (pG->pRoom)->pMessage;
            }
top_from_room:
            pMoji->Mess_top = pMoji->Mess_top + *(USHORT *)(pMoji->Mess_top + Mess_no * 2);
            return 0;
        case 0xc00:
            pMoji->Mess_top = (UCHAR *)Mess_no;
            return 0;
        default:
            return 0;
        }
        pMoji->Mess_top = pTop;
        return 0;
    }
}

/* DS 0x8003022c (Moji_trans_main) */
void Moji_trans_main(void)
{
    MOJIDISP *pMoji = &Moji;

    if ((pMoji->Mess_flg & 0x80) != 0) {
        Mess_disp(pMoji);
    }
    moji_trans_main(pMoji);
    Moji_buff_init();
    return;
}

/* DS 0x8003027c (Mess_disp) */
void Mess_disp(MOJIDISP *pMoji)
{
    UINT Vloop_ck;
    UCHAR D0;
    LONG msgCh;
    CHAR timeLeft;
    signed char Blink_t;
    UINT Item_id;
    UCHAR *pMess_end;
    UCHAR *pMess_p;
    LONG Loop_ctr;

    pMess_end = pMoji->Mess_end;
    Vloop_ck = (Main.Vloop == 0);
    switch (pMoji->Mess_r_no0) {
    case 0:
        pMoji->Mess_r_no0 = 1;
        D0 = (UCHAR)(1 << Vloop_ck);
        pMoji->Mess_time = D0;
        pMoji->Mess_wait = D0;
        pMoji->Mcol_init = 0;
        pMoji->Mcol_next = 0;
        pMess_end = pMoji->Mess_top;
        G.Status_flg &= ~STAT_PL_BUSY;
        G.Stop_flg |= pMoji->Stop_data;
        /* fall through */
    case 1:
        Loop_ctr = 1;
        timeLeft = pMoji->Mess_time;
        pMoji->Mess_time = timeLeft - 1;
        if (pMoji->Mess_type != 0 && (G.Key & 0x3000) != 0) {
            msgCh = timeLeft - 4;
            pMoji->Mess_time = msgCh;
            if (0 < (LONG)((ULONG)msgCh << 24)) break;
            msgCh = pMoji->Mess_wait;
            switch (msgCh) {
            case 0:
            case 1:
                Loop_ctr = 4;
                break;
            case 2:
                Loop_ctr = 2;
                break;
            case 3:
                Loop_ctr = 2;
                break;
            default:
                Loop_ctr = 1;
                break;
            }
        }
        if ((signed char)pMoji->Mess_time > 0) {
            pMoji->Mess_end = pMess_end;
            goto mess_trans_call;
        }
        goto text_scan;
        for (;;) {
            msgCh = *pMess_end;
            switch (msgCh) {
            case 0xfe:
                pMess_end++;
                if (*pMess_end == 0) {
                    pMoji->Mess_r_no0 = 5;
                }
                else {
                    pMoji->Mess_r_no0 = 6;
                    pMoji->Mess_time = (CHAR)(*pMess_end << Vloop_ck);
                }
                goto mess_end_set;
            case 0xfd:
                if (pMess_end[1] == 0) {
                    pMoji->Mess_r_no0 = 2;
                }
                else {
                    pMoji->Mess_r_no0 = 3;
                    pMoji->Mess_time = (CHAR)(pMess_end[1] << Vloop_ck);
                }
                pMess_end += 2;
                goto mess_end_set;
            case 0xfb:
                pMoji->Mess_r_no0 = 4;
                pMoji->Timer = (CHAR)(8 << Vloop_ck);
                goto mess_end_set;
            case 0xfa:
                pMess_p = pMess_end + 1;
                if (*pMess_p == 0) {
                    pMess_end += 2;
                    msgCh = *pMess_end;
                    while (msgCh != 0xfa) {
                        if (msgCh > 0xed && (msgCh < 0xf1 || (msgCh < 0xfa && msgCh > 0xf7))) {
                            pMess_end++;
                        }
                        pMess_end++;
                        msgCh = *pMess_end;
                    }
                    pMess_p = pMess_end + 1;
                }
                Item_id = 1;
                if (*pMess_p > 1) {
                    Item_id = *pMess_p >> 1;
                }
                pMoji->Mess_wait = (UCHAR)(Item_id << Vloop_ck);
                pMess_end = pMess_p;
                goto text_skip;
            case 0:
            case 0xf5:
            case 0xfc:
text_skip:
                pMess_end++;
                goto text_scan;
            case 0xf9:
                pMess_p = pMess_end + 1;
                pMess_end += 2;
                pMoji->Mcol_next = *pMess_p;
                goto text_scan;
            case 0xf8:
                pMoji->Mess_svp = pMess_end;
                msgCh = pMess_end[1];
                if (msgCh == 0) {
                    msgCh = pMoji->Mess_item;
                }
                pMess_end = name_ptr_set(msgCh);
                goto text_scan;
            case 0xf7:
                pMess_end = pMoji->Mess_svp + 2;
                goto text_scan;
            case 0xee:
            case 0xef:
            case 0xf0:
                pMess_end++;
                goto text_advance;
            default:
                break;
            }
text_scan:
            if (*pMess_end != 0 && *pMess_end < 0xee) {
text_advance:
                if (*pMess_end != 0) {
                    pMoji->Mess_flg |= 0x40;
                }
                pMess_end++;
                if ((pMoji->Mess_flg & 0x40) != 0) {
                    Loop_ctr--;
                }
                if (Loop_ctr == 0) {
                    pMoji->Mess_time = pMoji->Mess_wait;
                    goto mess_end_set;
                }
                goto text_scan;
            }
        }
    case 2:
        if ((G.Key_trg & 0x1000) != 0) {
            G.Key = 0xffff;
            pMoji->Mess_r_no0 = 1;
            D0 = pMoji->Mcol_next;
            timeLeft = (CHAR)(1 << Vloop_ck);
            pMoji->Mess_top = pMess_end;
            pMoji->Mess_time = timeLeft;
            pMoji->Mcol_init = D0;
        }
        else {
            Blink_t = pMoji->Mess_time - 1;
            pMoji->Mess_time = Blink_t;
            if (((LONG)Blink_t & (0x18 << Vloop_ck)) != 0) {
                if ((pMoji->Mess_attr & 0x400) != 0) {
                    ((PRINT14_VA)Print14)(0x6b, pMoji->Pos_y_def + 0x2a, 0, 3, s_Moji_next_mark_80010a1c, 0);
                }
                else {
                    ((PRINT14_VA)Print14)(0x99, pMoji->Pos_y_def + 0x1c, 0, 3, s_Moji_next_mark_80010a1c, 0);
                }
                pMoji->Mess_end = pMess_end;
                goto mess_trans_call;
            }
        }
        break;
    case 3:
        timeLeft = pMoji->Mess_time;
        pMoji->Mess_time = timeLeft - 1;
        if (timeLeft == 1) {
            pMoji->Mess_r_no0 = 1;
            D0 = pMoji->Mcol_next;
            pMoji->Mess_top = pMess_end;
            pMoji->Mess_time = (CHAR)(pMoji->Mess_wait << Vloop_ck);
            pMoji->Mcol_init = D0;
        }
        break;
    case 4:
        Item_id = pMess_end[1];
        if ((G.System_flg & 0x840) == 0x40) {
            Branch_disp(pMoji, (BRANCH_TBL *)(msg_space + (Item_id & 0xf) * 6 + 0xdc), Item_id, 1);
        }
        else {
            Branch_disp(pMoji, (BRANCH_TBL *)(msg_space + (Item_id & 0xf) * 6 + 0xb0), Item_id, 0);
        }
        pMoji->Mess_end = pMess_end;
        goto mess_trans_call;
    case 5:
        if ((G.Key_trg & 0x3000) != 0) {
            G.Key = 0xffff;
            goto mess_flag_off;
        }
        break;
    case 6:
        timeLeft = pMoji->Mess_time;
        pMoji->Mess_time = timeLeft - 1;
        if (timeLeft == 1) goto mess_flag_off;
        break;
    }
mess_end_set:
    pMoji->Mess_end = pMess_end;
mess_trans_call:
    mess_trans(pMoji);
    return;
mess_flag_off:
    pMoji->Mess_flg &= 0x7f;
    G.Stop_flg = pMoji->Stop_keep;
    return;
}

/* DS 0x80030844 (Branch_disp) */
void Branch_disp(MOJIDISP *pMoji, BRANCH_TBL *pBtbl, ULONG Flg, ULONG Mode)
{
    BOOL Wrapped;
    UCHAR D0;
    UINT Num;
    UINT Skip;
    ULONG M_ofs;
    ULONG Se_no;
    UINT Pos_x_sv;
    UINT Pos_y_sv;
    UINT Sel_no;
    ULONG Y;
    UINT Cur_x;
    UINT Pos_x;
    UINT Item_x;
    UINT i;
    INT Str_idx;
    INT Idx;

    Num = (UINT)pBtbl->Select_num;
    Skip = (UINT)pBtbl->Skip_size;
    M_ofs = (ULONG)pBtbl->Mess_ofs;
    Pos_x_sv = pMoji->Mess_pos_x;
    Sel_no = pMoji->Mess_flg & 0xf;
    Pos_y_sv = pMoji->Mess_pos_y;
    if (pMoji->Timer != 0) {
        pMoji->Timer--;
    }
    if ((G.Key_trg & 0x1000) == 0) {
        if ((G.Key_trg & 0x800) != 0) {
            Snd_se_stad(0x4040000, (VECTOR *)0x0);
            Wrapped = (Num - 1 == Sel_no);
            Sel_no++;
            if (Wrapped) {
                Sel_no = 0;
            }
            pMoji->Mess_time = 0;
        }
        if ((G.Key_trg & 0x400) != 0) {
            Snd_se_stad(0x4040000, (VECTOR *)0x0);
            if (Sel_no == 0) {
                Sel_no = Num;
            }
            Sel_no--;
            pMoji->Mess_time = 0;
        }
    }
    else if (pMoji->Timer == 0) {
        G.Key = 0xffff;
        pMoji->Mess_flg &= 0x7f;
        G.Stop_flg = pMoji->Stop_keep;
        if (((pMoji->Mess_attr & 0x2000) == 0) && ((Flg & 0x60) == 0)) {
            return;
        }
        if ((pMoji->Mess_flg & 0xf) == 0) {
            Se_no = 0x4060000;
            if ((Flg & 0x20) != 0) {
                return;
            }
        }
        else {
            Se_no = 0x4050000;
            if ((pMoji->Mess_flg & 0xf) != 1) {
                Se_no = 0x4060000;
            }
        }
        Snd_se_stad(Se_no, (VECTOR *)0x0);
        return;
    }
    D0 = pMoji->Mess_time - 1;
    pMoji->Mess_time = D0;
    if (Main.Vloop == 0) {
        D0 &= 0x30;
    }
    else {
        D0 &= 0x18;
    }
    if (D0 != 0) {
        Y = (ULONG)Pos_y_sv;
        Cur_x = (UINT)Pos_x_sv;
        if ((Flg & 0x80) == 0) {
            Y = pMoji->Pos_y_def + 0x10;
            Cur_x = (UINT)M_ofs;
        }
        ((PRINT14_VA)Print14)(Cur_x + Skip * Sel_no - 0xe, Y, 0, 0, s_Moji_sel_cursor_80010a40, 0);
    }
    Str_idx = (INT)((UINT)pBtbl->Str_no << 1);
    if ((Flg & 0x80) == 0) {
        i = 0;
        if (Num != 0) {
            Item_x = M_ofs;
            do {
                Idx = Str_idx + Mode;
                Str_idx += 2;
                i++;
                Mess_print(Item_x, pMoji->Pos_y_def + 0x10, branch_data + branch_ofs[Idx], Mode << 14 | 3);
                Item_x += Skip;
            } while (i < Num);
        }
    }
    else {
        i = 0;
        if (Num != 0) {
            Pos_x = (UINT)Pos_x_sv;
            do {
                Idx = Str_idx + Mode;
                Str_idx += 2;
                i++;
                Mess_print(Pos_x, (ULONG)Pos_y_sv, branch_data + branch_ofs[Idx], Mode << 14 | 3);
                Pos_x += Skip;
            } while (i < Num);
        }
    }
    pMoji->Mess_flg = (pMoji->Mess_flg & 0xf0) | (UCHAR)Sel_no;
    return;
}

/* DS 0x80030b9c (name_ptr_set) */
UCHAR *name_ptr_set(UCHAR Item_id)
{
    USHORT Ofs;
    UINT item_at;

    item_at = (UINT)Item_data_tbl[Item_id].Item_attribute;
    if ((G.System_flg & 0x840) == 0x40) {
        if (item_at != 0 && Flg_ck(G.SaveData.Item_c_flg, item_at) != 0) {
            return namelist_u_data + namelist_u_ofs[item_at + 0x81];
        }
        return namelist_u_data + namelist_u_ofs[Item_id];
    }
    if (item_at != 0 && Flg_ck(G.SaveData.Item_c_flg, item_at) != 0) {
        Ofs = namelist_tbl_ofs[item_at + 0x81];
    }
    else {
        Ofs = namelist_tbl_ofs[Item_id];
    }
    return namelist_tbl_data + Ofs;
}

/* DS 0x80030c9c (mess_trans) */
void mess_trans(MOJIDISP *pMoji)
{
    SPRT *pP;
    SPRT *pEnd;
    UCHAR *pMp;
    UCHAR *pMp_keep;
    DR_MODE *pOt;
    DR_MODE *pDr_mode;
    UCHAR D0;
    USHORT Attr;
    UINT Clt;
    UINT Cbuf;
    USHORT nextY;
    LONG Pos_xy;
    LONG Adv;
    LONG Glyph_v;
    UINT Msg_idx;

    pP = Moji.pPrim14_cur;
    Clt = 0x7810;
    Pos_xy = (LONG)(((ULONG)pMoji->Pos_y_def << 16) | pMoji->Pos_x_def);
    Cbuf = G.Cbuf_id;
    pEnd = Moji.Prim_sprt[Cbuf + 1];
    pMoji->Mess_pos_y = pMoji->Pos_y_def;
    if ((pMoji->Mess_attr & 0xf) != 0) {
        Adv = (pMoji->Mess_attr & 7) << 1;
    }
    else {
        Adv = 6;
    }
    pDr_mode = pMoji->Moji_mode[G.Cbuf_id] + Adv;
    Attr = pMoji->Mess_attr;
    if (pMoji->Mess_top != pMoji->Mess_end) {
        pMp = pMoji->Mess_top;
        do {
            Adv = 14;
            if (*pMp == 0) goto mess_zero;
            switch (*pMp) {
            case 0xfd:
                pMoji->Mess_pos_y = pMoji->Pos_y_def;
                /* fall through */
            case 0xfa:
                pMp++;
                /* fall through */
            case 0xfe:
                pMp++;
                pMoji->Mess_pos_y = pMoji->Pos_y_def;
                break;
            case 0xf9:
                pMp++;
                Clt = ((UINT)*pMp << 7) | 0x7810;
                pMp++;
                break;
            case 0xfc:
                pMp++;
                nextY = pMoji->Mess_pos_y + 0x10;
                Pos_xy = (LONG)(((ULONG)nextY << 16) | pMoji->Pos_x_def);
                pMoji->Mess_pos_y = nextY;
                break;
            case 0xee:
                pMp++;
                pOt = pDr_mode;
                pP->v0 = (UCHAR)((*pMp / 0x12) * 14 - 0x2e);
                goto mess_glyph;
            case 0xef:
                pMp++;
                pOt = pDr_mode + 1;
                pP->v0 = (UCHAR)((*pMp / 0x12) * 14);
                goto mess_glyph;
            case 0xf0:
                pMp++;
                pOt = pDr_mode + 1;
                pP->v0 = (UCHAR)((*pMp / 0x12) * 14 - 0x3c);
                goto mess_glyph;
            case 0xf8:
                D0 = pMp[1];
                if (D0 == 0) {
                    D0 = pMoji->Mess_item;
                }
                pMp_keep = pMp;
                pMp = name_ptr_set(D0);
                break;
            case 0xf7:
                pMp = pMp_keep + 2;
                break;
            case 0xf5:
                goto mess_adv;
            default:
                Glyph_v = (*pMp / 0x12) * 14 + 0x1c;
                pP->v0 = (UCHAR)Glyph_v;
                pOt = pDr_mode;
mess_glyph:
                if ((Attr & 0x4000) != 0 && *pMp < 0x57 && 1 < (UINT)(pMp[-1] - 0xee) && pMp[-1] != 0xf0) {
                    Msg_idx = (UINT)*pMp * 2;
                    Pos_xy = Pos_xy - (signed char)msg_space[Msg_idx];
                    Adv = (signed char)msg_space[Msg_idx + 1] + (signed char)msg_space[Msg_idx];
                }
                pP->u0 = (UCHAR)((*pMp % 0x12) * 14);
                pP->clut = (USHORT)Clt;
                *(LONG *)&pP->x0 = Pos_xy;
                *(ULONG *)&pP->r0 = 0x64808080;
                *(ULONG *)&pP->w = 0xe000e;
                AddPrim(pOt, pP);
                pP++;
                if (pP == pEnd) {
                    goto message_exit;
                }
                goto mess_adv;
mess_zero:
                if ((Attr & 0x4000) != 0) {
                    Pos_xy = Pos_xy - (signed char)msg_space[0];
                    Adv = (signed char)msg_space[1] + (signed char)msg_space[0];
                }
mess_adv:
                pMp++;
                Pos_xy += Adv;
                break;
            }
        } while (pMp != pMoji->Mess_end);
    }
message_exit:
    Moji.pPrim14_cur = pP;
    pMoji->Mess_pos_x = (USHORT)Pos_xy;
    return;
}

/* DS 0x80031070 (Name_disp) */
void Name_disp(long Pos_x, long Pos_y, ULONG Attr, ULONG Item_id)
{
    UCHAR *pName;
    UCHAR D0;
    LONG Adv;
    UINT Msg_idx;
    DR_MODE *pOt;
    UINT Prio;
    SPRT *pP;
    DR_MODE *pDr_mode;
    SPRT *pEnd;
    ULONG Y_hi;
    USHORT Clt;

    pP = Moji.pPrim14_cur;
    Adv = (Attr & 7) << 1;
    Prio = G.Cbuf_id;
    pEnd = Moji.Prim_sprt[Prio + 1];
    Y_hi = (ULONG)Pos_y << 16;
    if ((Attr & 7) == 0) {
        Adv = 6;
    }
    pDr_mode = Moji.Moji_mode[Prio] + Adv;
    Clt = (USHORT)((Attr & 0x30) << 3) | 0x7810;
    pName = name_ptr_set((UCHAR)Item_id);
    D0 = *pName;
    if (D0 != 0xf7) {
        do {
            Adv = 14;
            pOt = pDr_mode;
            switch (D0) {
            case 0:
                if ((Attr & 0x4000) != 0) {
                    Pos_x = Pos_x - (signed char)msg_space[0];
                    Adv = (signed char)msg_space[1] + (signed char)msg_space[0];
                }
                goto name_next;
            case 0xee:
                pName++;
                pP->v0 = (UCHAR)((*pName / 0x12) * 14 - 0x2e);
                break;
            case 0xef:
                pName++;
                pP->v0 = (UCHAR)((*pName / 0x12) * 14);
                pOt = pDr_mode + 1;
                break;
            case 0xf0:
                pName++;
                pP->v0 = (UCHAR)((*pName / 0x12) * 14 - 0x3c);
                pOt = pDr_mode + 1;
                break;
            default:
                pP->v0 = (UCHAR)((*pName / 0x12) * 14 + 0x1c);
                if ((Attr & 0x4000) != 0 && *pName < 0x57) {
                    Msg_idx = (UINT)*pName * 2;
                    Pos_x = Pos_x - (signed char)msg_space[Msg_idx];
                    Adv = (signed char)msg_space[Msg_idx + 1] + (signed char)msg_space[Msg_idx];
                }
                break;
            }
            /* DS stores the sprite as words: rgb+code, x0|y0, w|h */
            *(ULONG *)&pP->r0 = 0x64808080;
            *(ULONG *)&pP->w = 0x000e000e;
            *(ULONG *)&pP->x0 = ((ULONG)Pos_x & 0xffff) | Y_hi;
            pP->u0 = (UCHAR)((*pName % 0x12) * 14);
            pP->clut = Clt;
            AddPrim(pOt, pP);
            pP++;
            if (pP == pEnd) {
                Moji.pPrim14_cur = pP;
                return;
            }
name_next:
            pName++;
            D0 = *pName;
            Pos_x += Adv;
        } while (D0 != 0xf7);
    }
    Moji.pPrim14_cur = pP;
    return;
}

/* DS 0x800313a4 (Mess_print) */
void Mess_print(ULONG Pos_x, ULONG Pos_y, UCHAR *pMess, ULONG Attr)
{
    UCHAR D0;
    LONG Adv;
    LONG Glyph_v;
    UINT Clt;
    UINT Msg_idx;
    UINT Clut;
    ULONG Y_hi;
    ULONG Tag_hi;
    ULONG Tag_lo;
    SPRT *pP;
    SPRT *pEnd;
    DR_MODE *pOt;
    DR_MODE *pDr_mode;
    DR_MODE *pDr_alt;

    Clt = (UINT)G.Cbuf_id;
    D0 = *pMess;
    pDr_mode = Moji.Moji_mode[Clt] + (Attr & 7) * 2;
    pP = Moji.pPrim14_cur;
    pEnd = Moji.Prim_sprt[Clt + 1];
    pDr_alt = pDr_mode + 1;
    Clut = ((Attr & 0xf0) << 3) | 0x7810;
    Tag_hi = 0xff000000;
    Tag_lo = 0xffffff;
    Y_hi = Pos_y << 16;
    if (D0 != 0xfe) {
        do {
            Adv = 14;
            if (D0 == 0) {
                if ((Attr & 0x4000) != 0) {
                    Pos_x = Pos_x - (signed char)msg_space[0];
                    Adv = (signed char)msg_space[1] + (signed char)msg_space[0];
                }
                Pos_x += Adv;
                goto moji_next;
            }
            pOt = pDr_mode;
            switch (D0) {
            case 0xee:
                pMess++;
                Glyph_v = (*pMess / 0x12) * 14 - 0x2e;
                break;
            case 0xef:
                pMess++;
                Glyph_v = (*pMess / 0x12) * 14;
                pOt = pDr_alt;
                break;
            case 0xf0:
                pMess++;
                Glyph_v = (*pMess / 0x12) * 14 - 0x3c;
                pOt = pDr_alt;
                break;
            case 0xf5:
                goto moji_next;
            case 0xf6:
                Pos_x += 7;
                goto moji_next;
            case 0xf7:
            case 0xfe:
                return;
            default:
                Glyph_v = (*pMess / 0x12) * 14 + 0x1c;
                if ((Attr & 0x4000) != 0 && *pMess < 0x57) {
                    Msg_idx = (UINT)*pMess * 2;
                    Pos_x = Pos_x - (signed char)msg_space[Msg_idx];
                    Adv = (signed char)msg_space[Msg_idx + 1] + (signed char)msg_space[Msg_idx];
                }
                break;
            }
            pP->v0 = (UCHAR)Glyph_v;
            pP->w = 14;
            pP->h = 14;
            pP->r0 = 0x80;
            pP->g0 = 0x80;
            pP->b0 = 0x80;
            pP->code = 0x64;
            /* DS stores x0/y0 as one word (Pos_x | Pos_y << 16), so a negative Pos_x also fills y0 */
            *(ULONG *)&pP->x0 = Pos_x | Y_hi;
            D0 = *pMess;
            pP->clut = (USHORT)Clut;
            pP->u0 = (UCHAR)((D0 % 0x12) * 14);
            /* addPrim() expanded: keep the tag high byte, splice in the 24-bit address */
            *(ULONG *)pP = (*(ULONG *)pP & Tag_hi) | (pOt->tag & Tag_lo);
            pOt->tag = (pOt->tag & Tag_hi) | ((ULONG)pP & Tag_lo);
            pP++;
            if (pP == pEnd) {
                Moji.pPrim14_cur = pP;
                return;
            }
            Pos_x += Adv;
moji_next:
            pMess++;
            D0 = *pMess;
        } while (D0 != 0xfe);
    }
    Moji.pPrim14_cur = pP;
    return;
}

/* DS 0x800316a8 (moji_trans_main) */
void moji_trans_main(MOJIDISP *pMoji)
{
    UCHAR *pBuff0;
    UCHAR *pBuffEnd;
    LONG X;
    LONG Y;
    ULONG Pos;

    pBuffEnd = pMoji->pBuff_ptr;
    pBuff0 = pMoji->Moji_buff;
    if (pBuffEnd != pBuff0) {
        do {
            X = *(SHORT *)pBuff0;
            pBuff0 += sizeof(SHORT);
            Y = *(SHORT *)pBuff0;
            pBuff0 += sizeof(SHORT);
            Pos = X + (Y << 16);
            if ((*(USHORT *)pBuff0 & 0x200) != 0) {
                pBuff0 = moji_trans_14(pBuff0, Pos, pMoji);
            }
            else {
                pBuff0 = moji_trans_8(pBuff0, Pos, pMoji);
            }
        } while (pBuff0 < pBuffEnd);
    }
    return;
}

/* DS 0x80031734 (moji_trans_8) */
UCHAR *moji_trans_8(UCHAR *pBuff0, ULONG Pos, MOJIDISP *pMoji)
{
    USHORT Clt;
    UCHAR *pNextBuf;
    UINT D0;
    ULONG Keep_tag;
    UCHAR *pP;
    DR_MODE *pDr_mode;
    SPRT_8 *pSp;
    SPRT_8 *pBank_end;
    UCHAR c;
    ULONG Rgbc;
    ULONG Uv_clut;

    pBank_end = Moji.Prim_sprt_8[G.Cbuf_id + 1];
    if (Moji.pPrim8_cur == pBank_end) {
        pNextBuf = pMoji->pBuff_ptr;
    }
    else {
        Clt = *(USHORT *)pBuff0;
        pP = pBuff0 + 2;
        D0 = (Clt >> 8) & 1;
        pDr_mode = pMoji->Moji_mode[G.Cbuf_id] + (Clt & 7) * 2;
        Keep_tag = pDr_mode->tag;
        pSp = Moji.pPrim8_cur;
        /* DS builds the SPRT_8 words once: r0/g0/b0/code, and clut in the high half of the u0/v0/clut word */
        Rgbc = 0x74808080UL | (D0 << 25);
        Uv_clut = (ULONG)(USHORT)(((((Clt & 0xf0) >> 3) + D0 + 0x1e0) * 0x40) | 0x10) << 16;
        do {
            if (*pP != 0x20) {
                c = *pP - 0x20;
                *(ULONG *)&pSp->r0 = Rgbc;
                *(ULONG *)&pSp->x0 = Pos;
                *(ULONG *)&pSp->u0 = ((c & 0x1f) << 3) + ((c & 0xe0) << 6) + Uv_clut;
                pDr_mode->tag = (pDr_mode->tag & 0xff000000UL) | ((ULONG)pSp & 0xffffffUL);
                pDr_mode = (DR_MODE *)pSp;
                pSp++;
                Moji.pPrim8_cur = pSp;
                if (pSp == pBank_end) break;
            }
            pP++;
            Pos += 8;
        } while (*pP != 0);
        pNextBuf = (UCHAR *)((ULONG)(pP + 2) & 0xfffffffeUL);
        pDr_mode->tag = (pDr_mode->tag & 0xff000000UL) | (Keep_tag & 0xffffffUL);
    }
    return pNextBuf;
}

/* DS 0x800318a4 (moji_trans_14) */
UCHAR *moji_trans_14(UCHAR *pBuff0, ULONG Pos, MOJIDISP *pMoji)
{
    UCHAR D0;
    USHORT Clt;
    UCHAR *pNextBuf;
    UINT Prop;
    int i;
    int D1;
    int Adv;
    UCHAR *pP;
    DR_MODE *pDr_mode;
    SPRT *pSp;
    SPRT *pSp_cur;
    SPRT *pBank_end;
    ULONG Keep_tag;
    ULONG Rgbc;
    ULONG Uv_clut;

    pBank_end = Moji.Prim_sprt[G.Cbuf_id + 1];
    if (Moji.pPrim14_cur == pBank_end) {
        pNextBuf = pMoji->pBuff_ptr;
    }
    else {
        Clt = *(USHORT *)pBuff0;
        pP = pBuff0 + 2;
        D1 = (Clt >> 8) & 1;
        pDr_mode = pMoji->Moji_mode[G.Cbuf_id] + (Clt & 7) * 2;
        Keep_tag = pDr_mode->tag;
        pSp = Moji.pPrim14_cur;
        Rgbc = 0x64808080UL | ((ULONG)D1 << 25);
        Uv_clut = (ULONG)(USHORT)(((((Clt & 0xf0) >> 3) + D1 + 0x1e0) * 0x40) | 0x10) << 16;
        do {
            pSp_cur = pSp;
            Adv = 14;
            if (*pP == 0x20) {
                if ((Clt & 0x4000) != 0) {
                    Pos = Pos - (signed char)msg_space[0];
                    Adv = (signed char)msg_space[1] + (signed char)msg_space[0];
                }
            }
            else {
                Prop = *pP - 0x24;
                if ((Clt & 0x4000) != 0 && Prop < 0x57) {
                    i = Prop * 2;
                    Pos = Pos - (signed char)msg_space[i];
                    Adv = (signed char)msg_space[i + 1] + (signed char)msg_space[i];
                }
                /* DS builds the SPRT words: r0/g0/b0/code, x0/y0, w/h, then u0/v0/clut */
                *(ULONG *)&pSp_cur->r0 = Rgbc;
                *(ULONG *)&pSp_cur->x0 = Pos;
                D0 = *pP;
                *(ULONG *)&pSp_cur->w = 0xe000e;
                *(ULONG *)&pSp_cur->u0 = (UCHAR)(D0 % 0x12) * 14 + (((UCHAR)(D0 / 0x12) * 14) << 8) + Uv_clut;
                pDr_mode->tag = (pDr_mode->tag & 0xff000000UL) | ((ULONG)pSp_cur & 0xffffffUL);
                pDr_mode = (DR_MODE *)pSp_cur;
                pSp = pSp_cur + 1;
                Moji.pPrim14_cur = pSp;
                if (pSp == pBank_end) break;
            }
            pP++;
            Pos += Adv;
        } while (*pP != 0);
        pNextBuf = (UCHAR *)((ULONG)(pP + 2) & 0xfffffffeUL);
        pDr_mode->tag = (pDr_mode->tag & 0xff000000UL) | (Keep_tag & 0xffffffUL);
    }
    return pNextBuf;
}

/* DS 0x80031ac4 (Moji_buff_init) */
void Moji_buff_init(void)
{
    int i;
    ULONG *pBuff1;

    pBuff1 = (ULONG *)Moji.Moji_buff;
    i = 0xc0;
    do {
        *pBuff1 = 0;
        i--;
        pBuff1++;
    } while (i != 0);
    Moji.pBuff_ptr = Moji.Moji_buff;
    return;
}

/* DS 0x80031af4 (Moji_init) */
void Moji_init(void)
{
    USHORT tpage;
    int i;
    int j;
    int k;
    DR_MODE *pDr_mode;
    SPRT *pSpr;
    SPRT_8 *pSpr8;

    pDr_mode = Moji.Moji_mode[0];
    i = 0x10;
    do {
        tpage = GetTPage(0, 0, 0x300, 0x100);
        SetDrawMode(pDr_mode, 0, 0, tpage, (RECT *)0x0);
        tpage = GetTPage(0, 0, 0x340, 0x100);
        SetDrawMode(pDr_mode + 1, 0, 0, tpage, (RECT *)0x0);
        pDr_mode += 2;
        i--;
    } while (i != 0);
    pSpr = Moji.Prim_sprt[0];
    pSpr8 = Moji.Prim_sprt_8[0];
    j = 0x200;
    k = 0x300;
    do {
        pSpr->tag = 0x4000000;
        *(ULONG *)&pSpr->r0 = 0x64808080;
        j--;
        pSpr++;
    } while (j != 0);
    do {
        pSpr8->tag = 0x3000000;
        *(ULONG *)&pSpr8->r0 = 0x74808080;
        k--;
        pSpr8++;
    } while (k != 0);
    Moji_buff_init();
    Moji_mode_init();
    return;
}

/* DS 0x80031bf0 (Moji_mode_init) */
void Moji_mode_init(void)
{
    UINT i;
    DR_MODE *pDr_mode;
    ULONG *pOt;

    i = 8;
    pDr_mode = Moji.Moji_mode[G.Cbuf_id];
    pOt = (ULONG *)(G.Ot0 + G.Cbuf_id);
    do {
        AddPrim(pOt, pDr_mode);
        AddPrim(pOt, pDr_mode + 1);
        pDr_mode += 2;
        i--;
        pOt = pOt + 1;                      /* next OT entry (ULONG stride) */
    } while (i != 0);
    Moji.pPrim14_cur = Moji.Prim_sprt[G.Cbuf_id];
    Moji.pPrim8_cur = Moji.Prim_sprt_8[G.Cbuf_id];
    return;
}

